const pages = [
  ['OPERATIONS', 'overview', '◫', 'Overview'], ['OPERATIONS', 'projects', '◇', 'Projects'], ['OPERATIONS', 'providers', '⌁', 'Providers'],
  ['CAPACITY', 'profiles', '◎', 'Profiles / Accounts'], ['CAPACITY', 'models', '◌', 'Models'],
  ['EXECUTION', 'tasks', '✓', 'Tasks'], ['EXECUTION', 'routing', '⇢', 'Routing'], ['EXECUTION', 'decision-engines', '◈', 'Decision Engines'],
  ['CONTINUITY', 'memory', '▤', 'Memory'], ['CONTINUITY', 'handoffs', '⇄', 'Handoffs'], ['CONTINUITY', 'checkpoints', '◆', 'Checkpoints'],
  ['SYSTEM', 'locks', '⌑', 'Locks'], ['SYSTEM', 'audit', '≡', 'Audit / Logs'], ['SYSTEM', 'doctor', '✚', 'Doctor'], ['SYSTEM', 'settings', '⚙', 'Settings']
];
const titles = Object.fromEntries(pages.map(([, id,, label]) => [id, label]));
const workspace = document.querySelector('#workspace');
const state = { nonce: '', route: location.hash.slice(1) || 'overview', theme: 'system', selectedProject: '', memoryTab: 'context.md', cache: new Map(), pollBusy: new Set(), pollTimers: [], lastGoodRefresh: null };
const POLL_INTERVALS = Object.freeze({ tasks: 4_000, health: 12_000, static: 45_000 });

const e = (value = '') => String(value).replace(/[&<>'"]/g, (char) => ({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;' })[char]);
const clip = (value, length = 48) => { const text = String(value ?? '—'); return text.length > length ? `${text.slice(0, length - 1)}…` : text; };
const ago = (value) => { if (!value) return 'Never'; const ms = Date.now() - Date.parse(value); if (!Number.isFinite(ms)) return 'Unknown'; const units=[[864e5,'d'],[36e5,'h'],[6e4,'m'],[1e3,'s']]; for(const [size,label] of units) if(ms>=size) return `${Math.floor(ms/size)}${label} ago`; return 'just now'; };
const bytes = (value) => value == null ? 'Unknown' : value > 1e9 ? `${(value/1e9).toFixed(1)} GB` : value > 1e6 ? `${(value/1e6).toFixed(1)} MB` : `${Math.round(value/1e3)} KB`;
const duration = (seconds=0) => seconds >= 86400 ? `${Math.floor(seconds/86400)}d ${Math.floor(seconds%86400/3600)}h` : seconds >= 3600 ? `${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m` : `${Math.floor(seconds/60)}m`;
const badgeKind = (value='') => /healthy|active|available|completed|valid|ready|clean|ok|resumable/i.test(value) ? 'good' : /unavailable|failed|error|blocked|missing|corrupt|cancel/i.test(value) ? 'bad' : /degraded|running|review|unknown|pending|routing|waiting/i.test(value) ? 'warn' : 'neutral';
const badge = (value) => `<span class="badge ${badgeKind(value)}">${e(value ?? 'unknown')}</span>`;
const empty = (title, text, icon='◇') => `<div class="empty"><div class="empty-icon">${icon}</div><h3>${e(title)}</h3><p>${e(text)}</p></div>`;
const head = (title, description, actions='') => `<div class="page-head"><div><h2>${e(title)}</h2><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;
const metric = (label, value, note, key='') => `<article class="card metric" ${key?`data-metric="${e(key)}"`:''}><div class="metric-label">${e(label)}</div><div class="metric-value">${e(value)}</div><div class="metric-note">${e(note)}</div></article>`;
const jsonView = (value) => `<pre class="json">${e(JSON.stringify(value, null, 2))}</pre>`;

async function api(path, options = {}) {
  const response = await fetch(path, { ...options, headers: { ...(options.body ? {'content-type':'application/json'} : {}), ...(state.nonce ? {'x-ai-router-control':state.nonce} : {}), ...(options.headers ?? {}) } });
  const nonce = response.headers.get('x-ai-router-control'); if (nonce) state.nonce = nonce;
  const value = await response.json().catch(() => ({ error:'INVALID_RESPONSE', message:'The local service returned an invalid response.' }));
  if (!response.ok) { const error = new Error(value.message || 'Request failed.'); error.code = value.error || 'REQUEST_FAILED'; throw error; }
  return value;
}
const post = (path, value={}) => api(path, { method:'POST', headers:{origin:location.origin}, body:JSON.stringify(value) });

function toast(message, kind='') { const item=document.createElement('div'); item.className=`toast ${kind}`; item.textContent=message; document.querySelector('#toast-region').append(item); setTimeout(()=>item.remove(),4200); }
function closeOverlays(){ document.querySelector('#drawer-root').innerHTML=''; document.querySelector('#modal-root').innerHTML=''; }
function modal(title, body, submitLabel, onSubmit) {
  document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" data-close><section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${e(title)}</h2><button class="close" data-close aria-label="Close">×</button></div><form class="modal-body" id="modal-form">${body}<div class="modal-actions"><button type="button" class="button ghost" data-close>Cancel</button><button class="button primary" type="submit">${e(submitLabel)}</button></div></form></section></div>`;
  document.querySelector('#modal-form').addEventListener('submit', async event => { event.preventDefault(); const button=event.submitter; button.disabled=true; try { await onSubmit(Object.fromEntries(new FormData(event.currentTarget))); closeOverlays(); await render(); } catch(error){toast(`${error.code}: ${error.message}`,'bad');button.disabled=false;} });
}
function drawer(title, content) { document.querySelector('#drawer-root').innerHTML=`<div class="drawer-backdrop" data-close><aside class="drawer" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="drawer-head"><h2>${e(title)}</h2><button class="close" data-close aria-label="Close">×</button></div><div class="drawer-body">${content}</div></aside></div>`; }

function renderNavigation() {
  let group=''; document.querySelector('#navigation').innerHTML=pages.map(([next,id,icon,label])=>{const heading=next!==group?`<div class="nav-group-label">${next}</div>`:'';group=next;return `${heading}<button class="nav-link ${state.route===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icon}</span>${label}</button>`;}).join('');
}
function pageChrome() { renderNavigation(); document.querySelector('#page-title').textContent=titles[state.route]||'Overview'; document.querySelector('#page-eyebrow').textContent=pages.find(([,id])=>id===state.route)?.[0]||'OPERATIONS'; document.body.classList.remove('menu-open'); }

async function overview() {
  const results=await Promise.allSettled([api('/api/status'),api('/api/projects'),api('/api/providers'),api('/api/tasks'),api('/api/audit')]);
  const [status,projects,providers,tasks,audit]=[results[0].value??{status:'degraded',counts:{projects:0,providers:0,healthy_providers:0,active_tasks:0}},results[1].value??[],results[2].value??[],results[3].value??[],results[4].value??[]];
  const unavailable=results.map((result,index)=>result.status==='rejected'?['status','projects','providers','tasks','audit'][index]:null).filter(Boolean);
  const active=tasks.filter(x=>!['COMPLETED','CANCELLED'].includes(x.state?.state)); const lastRoute=audit.find(x=>x.type==='route_selected');
  return `${head('System overview','A live, local view of routing capacity, project continuity, and durable execution.')}${unavailable.length?`<div class="notice warn" style="margin-bottom:16px">Some sources are temporarily unavailable: ${e(unavailable.join(', '))}. Other operational state remains visible.</div>`:''}
  <section class="grid metrics">${metric('Registered projects',status.counts.projects,`${projects.filter(x=>x.status==='active').length} active`,'projects')}${metric('Available providers',status.counts.healthy_providers,`${status.counts.providers} registered`,'providers')}${metric('Active tasks',status.counts.active_tasks,`${tasks.length} durable records`,'tasks')}${metric('Continuity health',projects.filter(x=>x.memory_initialized).length,`${projects.length-projects.filter(x=>x.memory_initialized).length} need memory`,'continuity')}</section>
  <section class="grid two"><article class="card"><div class="card-header"><div><h3>Health map</h3><p>Current local dependencies and durable state</p></div><span id="overview-system-status">${badge(status.status)}</span></div><div class="health-list" id="overview-health-list">
  ${healthItem('Control service','healthy',`127.0.0.1 · uptime ${duration(status.control?.uptime_seconds)}`,'control')}${providers.map(p=>healthItem(p.name,p.health.status,`${p.health.model_count??0} models`,`provider-${p.id}`)).join('')}${healthItem('Project memory',projects.every(p=>p.memory_initialized)?'healthy':'review',`${projects.filter(p=>p.memory_initialized).length}/${projects.length} initialized`,'memory')}${healthItem('Task execution',active.length?'running':'ready',`${active.length} active`,'tasks')}</div></article>
  <article class="card"><div class="card-header"><div><h3>Recent activity</h3><p>Latest sanitized audit events</p></div><button class="button small ghost" data-nav="audit">View all</button></div><div id="overview-activity">${audit.length?`<ul class="activity-list">${audit.slice(0,7).map(activity).join('')}</ul>`:empty('No audit events','Events will appear as the router performs local operations.','≡')}</div></article></section>
  <section class="card section-gap"><div class="card-header"><div><h3>Last routing decision</h3><p>Why the most recent candidate was chosen</p></div><button class="button small" data-nav="routing">Explain a route</button></div><div id="overview-routing">${routingSummary(lastRoute)}</div></section>`;
}
function healthItem(name,status,note,key=''){return `<div class="health-item" ${key?`data-health="${e(key)}"`:''}><div><strong>${e(name)}</strong><small>${e(note)}</small></div>${badge(status)}</div>`;}
function activity(item){return `<li class="activity-item"><span class="activity-dot"></span><div><strong>${e(item.type.replaceAll('_',' '))}</strong><p>${e([item.project_id,item.task_id,item.provider_id].filter(Boolean).join(' · ')||'System event')}</p></div><time>${ago(item.at)}</time></li>`;}
function routingSummary(lastRoute){return lastRoute?`<div class="route-summary"><div class="route-winner"><small>Selected route</small><strong>${e(lastRoute.provider_id||'Provider')}</strong><span class="muted mono">${e(lastRoute.profile_id||'default')}</span></div><div><p class="muted">${e(lastRoute.task_id||'Latest routing event')}</p><div class="reason-list"><span class="reason">cost policy satisfied</span><span class="reason">capabilities matched</span><span class="reason">health accepted</span></div></div></div>`:empty('No routing decision yet','Use Routing to inspect candidates without executing a task.','⇢');}

async function projectsPage(){const projects=await api('/api/projects');return `${head('Projects','Registered workspaces, repository state, and continuity readiness.',`<button class="button" data-action="scan-projects">↻ Scan roots</button><button class="button primary" data-action="register-project">＋ Register project</button>`)}<article class="card">${projects.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>Status</th><th>Git</th><th>Memory</th><th>Active task</th><th></th></tr></thead><tbody>${projects.map(p=>`<tr data-project-id="${e(p.projectId)}"><td><div class="row-title">${e(p.displayName)}</div><div class="row-sub mono">${e(p.workspacePath)}</div></td><td data-project-status>${badge(p.status)}</td><td data-project-git>${badge(p.git?.dirty===false?'clean':p.git?.isRepository?'changed':'not git')}</td><td data-project-memory>${badge(p.memory_status)}</td><td data-project-task>${p.active_task?`<span class="mono">${e(p.active_task.task_id)}</span>`:'—'}</td><td><div class="actions"><button class="button small" data-action="project-detail" data-id="${e(p.projectId)}">Inspect</button><button class="button small" data-action="project-memory" data-id="${e(p.projectId)}">Memory</button>${!p.memory_initialized?`<button class="button small primary" data-action="init-memory" data-id="${e(p.projectId)}">Initialize</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No projects registered','Register a workspace or scan a configured project root.','◇')}</article>`;}

async function providersPage(){const providers=await api('/api/providers');return `${head('Providers','Registered execution providers. Authentication and models remain isolated per profile.',`<button class="button" data-action="test-providers">↻ Test connections</button>`)}<section class="grid three">${providers.map(p=>`<article class="card provider-card" data-provider-id="${e(p.id)}"><div class="provider-top"><div class="provider-identity"><span class="provider-logo">${e(p.name.slice(0,2).toUpperCase())}</span><div><h3>${e(p.name)}</h3><p>${e(p.type)} provider · ${e(p.id)}</p></div></div><span data-provider-status>${badge(p.enabled?p.health.status:'disabled')}</span></div><div class="mini-grid"><div class="mini-stat"><span>Models</span><strong data-provider-models>${e(p.health.model_count??'Unknown')}</strong></div><div class="mini-stat"><span>Strength</span><strong>${e(p.strength_class)}</strong></div><div class="mini-stat"><span>Auth</span><strong>${e((p.authentication_modes||[]).join(', '))}</strong></div><div class="mini-stat"><span>Channel</span><strong>${e(p.id==='openai'?'Codex subscription':p.type==='local'?'Local HTTP':'Provider API')}</strong></div></div><div class="reason-list">${(p.capabilities||[]).map(x=>`<span class="reason">${e(x)}</span>`).join('')}</div><div class="divider"></div><div class="actions"><button class="button ${p.enabled?'danger':'primary'} small" data-action="provider-toggle" data-id="${e(p.id)}" data-enabled="${p.enabled}">${p.enabled?'Disable':'Enable'}</button><button class="button small" data-action="discover-models">Discover models</button></div></article>`).join('')}</section>`;}

async function decisionEnginesPage(){const s=await api('/api/decision-engines/status');const last=s.last_decision;return `${head('Decision Engines','Optional classification layers. AI Router remains authoritative and hard policy always applies.')}<section class="grid two"><article class="card provider-card" id="jev-status-card"><div class="provider-top"><div class="provider-identity"><span class="provider-logo">JV</span><div><h3>Jev Decision Engine</h3><p>Optional ${e(s.engine.type)} · protocol ${e(s.protocol_version)}</p></div></div><span data-jev="health">${badge(s.health.status)}</span></div><div class="mini-grid"><div class="mini-stat"><span>Enabled</span><strong data-jev="enabled">${s.enabled?'Yes':'No'}</strong></div><div class="mini-stat"><span>Mode</span><strong data-jev="mode">${e(s.mode.replaceAll('_',' '))}</strong></div><div class="mini-stat"><span>Transport</span><strong>${e(s.transport)}</strong></div><div class="mini-stat"><span>Threshold</span><strong>${Math.round(s.confidence_threshold*100)}%</strong></div><div class="mini-stat"><span>Last decision</span><strong data-jev="last-decision">${last?.at?ago(last.at):'Never'}</strong></div><div class="mini-stat"><span>Last latency</span><strong data-jev="latency">${last?.latency_ms==null?'Unknown':`${e(last.latency_ms)} ms`}</strong></div><div class="mini-stat"><span>Last confidence</span><strong data-jev="confidence">${last?.confidence==null?'Unknown':`${Math.round(last.confidence*100)}%`}</strong></div><div class="mini-stat"><span>Fallback</span><strong>${s.fallback_enabled?e(s.fallback_engine):'Off'}</strong></div><div class="mini-stat"><span>Usage / estimated cost</span><strong>${s.usage.monthly.estimated_cost==null?'Unknown':e(s.usage.monthly.estimated_cost)}</strong></div><div class="mini-stat"><span>Last error</span><strong data-jev="error">${e(last?.fallback_reason||'None')}</strong></div></div><div class="notice section-gap">Real Jev connection not enabled yet. No credentials are requested or stored by this dashboard.</div><button class="button section-gap" data-action="connect-jev">Connect Jev</button></article><article class="card card-pad"><h3>Current authority chain</h3><div class="timeline section-gap"><div class="timeline-step done"><div class="step-dot">1</div><span>Hard policy gate</span></div><div class="timeline-step ${s.enabled?'current':'done'}"><div class="step-dot">2</div><span>${s.enabled?'Jev classification':'Jev skipped'}</span></div><div class="timeline-step done"><div class="step-dot">3</div><span>Deterministic final policy</span></div></div><p class="muted">Disabled, unavailable, timed out, malformed, low-confidence, rate-limited, or over-budget Jev evaluations fall back to the deterministic router.</p></article></section>`;}

async function profilesPage(){const settings=await api('/api/settings');const profiles=await api(`/api/profiles${settings.developer_test_mode?'?include_test=true':''}`);state.visibleProfiles=profiles;return `${head('Profiles / Accounts','Independent provider identities. Connection tests and Test Chat never access projects or tools.',`<button class="button primary" data-action="add-profile">＋ Add Profile</button>`)}<div class="toolbar"><label class="check-row"><input type="checkbox" id="developer-test-mode" ${settings.developer_test_mode?'checked':''}> Developer/Test Mode</label><span class="muted">${settings.developer_test_mode?'Synthetic and mock profiles are visible.':'Synthetic and mock profiles are hidden.'}</span></div><section class="grid three section-gap">${profiles.length?profiles.map(profileCard).join(''):empty('No usable profiles','Add a provider profile. Authentication will not start automatically.','◎')}</section>`;}
function profileCard(p){const model=p.selected_model_id||p.models?.[0]?.model_id||'Not configured';const connected=['connected','model-required','ready','available'].includes(p.status);return `<article class="card provider-card" data-profile-id="${e(p.profile_id)}"><div class="provider-top"><div class="provider-identity"><span class="provider-logo">${e(p.provider_id.slice(0,2).toUpperCase())}</span><div><h3>${e(p.display_name)}</h3><p class="mono">${e(p.provider_id)} · ${e(p.profile_id)}</p></div></div>${badge(p.enabled?p.status:p.status==='unconfigured'?'unconfigured':'disabled')}</div><div class="mini-grid"><div class="mini-stat"><span>Model</span><strong title="${e(model)}">${e(model)}</strong></div><div class="mini-stat"><span>Location</span><strong>${e(p.location)}</strong></div><div class="mini-stat"><span>Cost</span><strong>${e(p.cost_category)}</strong></div><div class="mini-stat"><span>Last success</span><strong>${ago(p.last_successful_use)}</strong></div></div><div class="actions"><button class="button small primary" data-action="profile-connect" data-connect-action="${connected?'reconnect':'connect'}" data-id="${e(p.profile_id)}">${connected?'Reconnect':'Connect'}</button><button class="button small" data-action="profile-disconnect" data-id="${e(p.profile_id)}">Disconnect</button><button class="button small" data-action="profile-toggle" data-id="${e(p.profile_id)}" data-enabled="${p.enabled}">${p.enabled?'Disable':'Enable'}</button><button class="button small" data-action="profile-edit" data-id="${e(p.profile_id)}">Edit</button><button class="button small" data-action="profile-test-connection" data-id="${e(p.profile_id)}">Test Connection</button><button class="button small" data-action="profile-test-chat" data-id="${e(p.profile_id)}" data-provider="${e(p.provider_id)}">Test Chat</button><button class="button small danger" data-action="profile-delete" data-id="${e(p.profile_id)}">Delete Profile</button></div></article>`;}

const discoveryErrorMessage=code=>({MODEL_PROVIDER_NOT_REGISTERED:'This provider is not connected yet, so its real model list is unavailable.',MODEL_DISCOVERY_NOT_SUPPORTED:'This provider connector does not support model discovery.',PROFILE_CREDENTIAL_MISSING:'Save this profile, then use Connect to validate a credential before discovering models.',OPENAI_SUBSCRIPTION_AUTH_NOT_PUBLIC:'A supported isolated OpenAI subscription login is not available for this dashboard.',PROVIDER_DISABLED:'Enable this provider before discovering models.',MODEL_DISCOVERY_FAILED:'Model discovery failed. Check the provider connection and try again.',OLLAMA_UNAVAILABLE:'Ollama is not reachable. Start the local service and try again.'}[code]||`Model discovery failed (${code||'unknown error'}).`);
const modelOptionLabel=model=>`${model.model_id}${model.profile_metadata?.is_free?' — FREE':''} · ${(model.profile_metadata?.model_types||['Type unknown']).join(', ')}`;
function modelSummary(model,form){if(!model)return '<div class="notice">Select a model to see its details.</div>';const meta=model.profile_metadata||{},facts=model.discovered_facts||{};const capabilities=meta.capabilities?.length?meta.capabilities.join(', '):'Unknown';const cost=meta.is_free?'Free':form?.elements.cost_category?.value||'Unknown';const loaded=meta.loaded===true?'Loaded':meta.loaded===false?'Unloaded':'Unknown';return `<div class="model-summary"><div><span>Model</span><strong class="mono">${e(model.model_id)}</strong></div><div><span>Provider</span><strong>${e(model.provider_id)}</strong></div><div><span>Type</span><strong>${e((meta.model_types||['Unknown']).join(', '))}</strong></div><div><span>Location</span><strong>${e(meta.locality||'Unknown')}</strong></div><div><span>Context</span><strong>${e(meta.context_size??'Unknown')}</strong></div><div><span>Cost</span><strong>${e(cost)}</strong></div><div><span>Loaded</span><strong>${e(loaded)}</strong></div><div class="wide"><span>Capabilities</span><strong>${e(capabilities)}</strong></div>${facts.family?`<div class="wide"><span>Family</span><strong>${e(facts.family)}</strong></div>`:''}</div>`;}

async function profileEditor(profile=null){
  const providers=await api('/api/providers');const known=[...new Map([...providers.map(p=>[p.id,p.name]),['openai','OpenAI'],['gemini','Gemini'],['openrouter','OpenRouter'],['ollama','Ollama']]).entries()];const providerTypes=new Map([...providers.map(p=>[p.id,p.type]),['openai','cloud'],['gemini','cloud'],['openrouter','gateway'],['ollama','local']]);const initialProvider=profile?.provider_id||known[0]?.[0]||'ollama';let discovered=[];
  document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" data-close><section class="modal modal-wide" role="dialog" aria-modal="true" aria-label="${profile?'Edit Profile':'Add Profile'}"><div class="modal-head"><h2>${profile?'Edit Profile':'Add Profile'}</h2><button class="close" data-close aria-label="Close">×</button></div><form class="modal-body" id="profile-editor"><div class="form-grid"><div class="field"><label>Provider</label><select class="select" id="profile-provider" name="provider_id" ${profile?'disabled':''}>${known.map(([id,name])=>`<option value="${e(id)}" ${(profile?.provider_id||initialProvider)===id?'selected':''}>${e(name)}</option>`).join('')}</select>${profile?`<input type="hidden" name="provider_id" value="${e(profile.provider_id)}">`:''}</div><div class="field"><label>Profile ID</label><input class="input" name="profile_id" required pattern="[a-z0-9][a-z0-9._-]{1,63}" value="${e(profile?.profile_id||'')}" ${profile?'readonly':''}></div><div class="field wide"><label>Display name</label><input class="input" name="display_name" required maxlength="120" value="${e(profile?.display_name||'')}"></div><div class="field wide model-picker"><div class="split"><label>Model</label><label class="check-row"><input type="checkbox" id="profile-model-advanced"> Advanced: show all models</label></div><select class="select" id="profile-model" name="selected_model_id" required disabled><option value="">Loading models…</option></select><div class="model-controls" id="openrouter-model-controls" hidden><label>OpenRouter cost filter</label><select class="select" id="profile-model-cost"><option value="all">Free and paid</option><option value="free">Free only</option><option value="paid">Paid only</option></select></div><small class="muted" id="profile-model-status">Discovering real provider models…</small></div><div class="field wide" id="provider-default-field" hidden><label class="check-row"><input type="checkbox" name="use_provider_default"> Use provider default model</label></div><div class="wide" id="profile-model-summary"><div class="notice">Model details will appear after discovery.</div></div><div class="field"><label>Location</label><select class="select" name="location"><option value="local" ${!profile||profile.location==='local'?'selected':''}>Local</option><option value="cloud" ${profile?.location==='cloud'?'selected':''}>Cloud</option></select></div><div class="field"><label>Cost category</label><select class="select" name="cost_category">${['LOCAL','SUBSCRIPTION_INCLUDED','METERED_LOW','METERED_MEDIUM','METERED_HIGH','UNKNOWN'].map(x=>`<option value="${x}" ${profile?.cost_category===x||profile?.cost_category?.toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field wide"><label>Authentication mode</label><input class="input" name="auth_mode" value="${e(profile?.auth_mode||'not-configured')}" readonly><small class="muted">No authentication is started automatically. Credentials belong in a backend secret store.</small></div></div><div class="modal-actions"><button type="button" class="button ghost" data-close>Cancel</button><button class="button primary" id="profile-save" type="submit" disabled>${profile?'Save profile':'Add profile'}</button></div></form></section></div>`;
  const form=document.querySelector('#profile-editor'),providerSelect=document.querySelector('#profile-provider'),modelSelect=document.querySelector('#profile-model'),advanced=document.querySelector('#profile-model-advanced'),costFilter=document.querySelector('#profile-model-cost'),status=document.querySelector('#profile-model-status'),summary=document.querySelector('#profile-model-summary'),save=document.querySelector('#profile-save');
  const requiresModel=()=>providerTypes.get(providerSelect.value)==='local'||discovered.length>0;
  form.elements.cost_category.insertAdjacentHTML('afterbegin','<option value="FREE">FREE</option>');
  if(profile?.cost_category==='FREE')form.elements.cost_category.value='FREE';
  if(!profile&&initialProvider==='openrouter')costFilter.value='free';
  function compatibleModels(){const provider=providerSelect.value;return discovered.filter(item=>item.model_id&&(advanced.checked||item.profile_metadata?.chat_compatible!==false)&&(provider!=='openrouter'||costFilter.value==='all'||(costFilter.value==='free')===Boolean(item.profile_metadata?.is_free)));}
  function updateSummary(){const selected=discovered.find(item=>item.model_id===modelSelect.value)||profile?.models?.find(item=>item.model_id===modelSelect.value);if(providerSelect.value==='openrouter'&&selected)form.elements.cost_category.value=selected.profile_metadata?.is_free?'FREE':'METERED_LOW';summary.innerHTML=modelSummary(selected,form);}
function populate(preferred=''){
  const choices=compatibleModels();
  const previous=preferred||modelSelect.value;

  modelSelect.innerHTML='';

  if(choices.length>1){
    modelSelect.insertAdjacentHTML(
      'beforeend',
      '<option value="">Select a model…</option>'
    );
  }

  for(const model of choices){
    modelSelect.insertAdjacentHTML(
      'beforeend',
      `<option value="${e(model.model_id)}">${e(modelOptionLabel(model))}</option>`
    );
  }

  if(previous&&choices.some(item=>item.model_id===previous)){
    modelSelect.value=previous;
  }else if(choices.length===1){
    modelSelect.value=choices[0].model_id;
  }else{
    modelSelect.value='';
  }

  modelSelect.disabled=choices.length===0;

  save.disabled=requiresModel()&&!modelSelect.value;

  status.textContent=
    choices.length===1
      ? 'One compatible model found and selected automatically.'
      : choices.length>1
        ? `${choices.length} compatible models found. Choose one to continue.`
        : discovered.some(item=>item.model_id)
          ? 'No compatible chat model matches the current filters. Enable Advanced to show embedding-only models.'
          : providerTypes.get(providerSelect.value)==='local'
            ? 'No models were returned by this provider.'
            : 'No models are available yet. You can save this profile now and connect it later to discover models.';

  updateSummary();
}
  async function discover(){const provider=providerSelect.value;discovered=[];modelSelect.disabled=true;save.disabled=true;modelSelect.innerHTML='<option value="">Loading models…</option>';status.innerHTML='<span class="inline-spinner"></span> Querying the selected provider…';summary.innerHTML='<div class="notice">Loading model metadata…</div>';document.querySelector('#openrouter-model-controls').hidden=provider!=='openrouter';try{const modelsPath=`/api/models?provider=${encodeURIComponent(provider)}&detailed=true&refresh=true`;const profileQuery=profile?.profile_id?`&profile=${encodeURIComponent(profile.profile_id)}`:'';const result=await api(`${modelsPath}${profileQuery}`);const failure=result.find(item=>!item.model_id&&item.error_code);if(failure)throw Object.assign(new Error(discoveryErrorMessage(failure.error_code)),{code:failure.error_code});discovered=result.filter(item=>item.model_id);document.querySelector('#provider-default-field').hidden=!discovered.some(item=>item.provider_default_supported===true);populate(profile?.selected_model_id||profile?.models?.[0]?.model_id||'');}catch(error){modelSelect.innerHTML='<option value="">Models unavailable</option>';status.textContent=discoveryErrorMessage(error.code);summary.innerHTML=`<div class="notice warn">${e(status.textContent)} ${requiresModel()?'This local profile cannot be saved without a model.':'You can save this cloud profile now and connect it later.'}</div>`;save.disabled=requiresModel();}}
  providerSelect.addEventListener('change',()=>{const local=providerTypes.get(providerSelect.value)==='local';form.elements.location.value=local?'local':'cloud';if(providerSelect.value==='openrouter')costFilter.value='free';if(!local&&form.elements.cost_category.value==='LOCAL')form.elements.cost_category.value='UNKNOWN';discover();});advanced.addEventListener('change',()=>populate());costFilter.addEventListener('change',()=>populate());modelSelect.addEventListener('change',()=>{save.disabled=requiresModel()&&!modelSelect.value;updateSummary();});form.elements.cost_category.addEventListener('change',updateSummary);
form.addEventListener('submit',async event=>{
  event.preventDefault();

  const button=event.submitter;
  button.disabled=true;

  try{
    const data=Object.fromEntries(new FormData(form));

    const selected=discovered.find(item=>item.model_id===data.selected_model_id)||profile?.models?.find(item=>item.model_id===(data.selected_model_id||profile?.selected_model_id));

    if(requiresModel() && !selected){
      throw Object.assign(
        new Error('Choose an available model before saving.'),
        {code:'MODEL_REQUIRED'}
      );
    }

    if(!selected){
      data.selected_model_id=null;
    }

    await post('/api/profiles',{
      ...data,
      enabled:selected ? (profile?.enabled??true) : false,
      models:selected ? [selected] : []
    });

    closeOverlays();
    await render();

  }catch(error){
    toast(
      `${error.code}: ${error.message}`,
      'bad'
    );
    button.disabled=false;
  }
});
discover();
}

function profileConnect(profile,connectAction='connect'){
  if(profile.provider_id==='openai')return drawer('OpenAI / Codex subscription',`<div class="notice warn"><strong>Isolated subscription login is not started.</strong><p class="section-gap">AI Router will not copy the Codex Desktop/CLI session or request your ChatGPT password. OpenAI does not expose a supported public embedded OAuth flow for this third-party dashboard, so this connector remains explicitly blocked instead of silently using metered API billing.</p></div><div class="model-summary section-gap"><div><span>Provider</span><strong>OpenAI</strong></div><div><span>Execution channel</span><strong>Codex subscription</strong></div><div><span>Status</span><strong>Official auth integration blocked</strong></div><div><span>Metered API</span><strong>Not enabled</strong></div></div>`);
  if(profile.provider_id==='ollama')return post(`/api/profiles/${encodeURIComponent(profile.profile_id)}/${connectAction}`).then(result=>{toast(result.message||'Ollama connection validated.');return render();});
  const isGemini=profile.provider_id==='gemini';
  return modal(`${connectAction==='reconnect'?'Reconnect':'Connect'} ${profile.display_name}`,`<div class="notice ${isGemini?'warn':''}">${isGemini?'Gemini programmatic access is metered. It remains disabled unless you explicitly opt in below.':'The API key is sent only to the local AI Router service, validated with OpenRouter, encrypted with Windows DPAPI, and never returned to the browser.'}</div><div class="form-grid section-gap"><div class="field wide"><label>${isGemini?'Gemini API key':'OpenRouter API key'}</label><input class="input" type="password" name="credential" autocomplete="new-password" required maxlength="32768"></div>${isGemini?'<label class="check-row wide"><input type="checkbox" name="metered_opt_in" required> I understand this provider may charge metered API usage.</label>':''}</div>`,connectAction==='reconnect'?'Reconnect':'Validate and connect',async data=>post(`/api/profiles/${encodeURIComponent(profile.profile_id)}/${connectAction}`,{credential:data.credential,metered_opt_in:data.metered_opt_in==='on'}));
}

async function profileTestChat(profileId,providerId){const profile=(state.visibleProfiles||[]).find(item=>item.profile_id===profileId);const configured=profile?.selected_model_id||profile?.models?.[0]?.model_id||'';let models=[];try{models=(await api(`/api/models?provider=${encodeURIComponent(providerId)}&detailed=true`)).filter(item=>item.model_id&&item.profile_metadata?.chat_compatible!==false);}catch{}if(configured&&!models.some(item=>item.model_id===configured))models.unshift(profile?.models?.find(item=>item.model_id===configured)||{model_id:configured,provider_id:providerId});document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" data-close><section class="modal" role="dialog" aria-modal="true" aria-label="Test Chat"><div class="modal-head"><h2>Test Chat — connection/model test</h2><button class="close" data-close aria-label="Close">×</button></div><form class="modal-body" id="profile-test-form"><div class="notice">Isolated inference only: no project files, tools, memory, Git, tasks, or routing.</div><div class="form-grid section-gap"><div class="field wide"><label>Message</label><input class="input" name="message" required maxlength="500" value="Reply only with OK"></div><div class="field wide"><label>Model</label><select class="select" id="test-chat-model" name="model" required>${models.length?models.map(item=>`<option value="${e(item.model_id)}" ${item.model_id===configured?'selected':''}>${e(item.model_id)}${item.model_id===configured?' — profile model':''}</option>`).join(''):'<option value="">No available chat model</option>'}</select><small class="model-source" id="test-chat-model-source">${configured?'Using the model configured for this profile.':'No profile model is configured; choose an available model.'}</small></div><div class="field"><label>Maximum output tokens</label><input class="input" name="max_output_tokens" type="number" min="1" max="256" value="32"></div></div><div id="profile-test-result" class="section-gap"></div><div class="modal-actions"><button type="button" class="button ghost" data-close>Close</button><button class="button primary" type="submit">Run Test Chat</button></div></form></section></div>`;const modelField=document.querySelector('#test-chat-model'),source=document.querySelector('#test-chat-model-source');modelField.addEventListener('change',()=>{const override=Boolean(configured&&modelField.value!==configured);source.textContent=override?`Temporary override: ${modelField.value}. The saved profile model remains ${configured}.`:'Using the model configured for this profile.';source.classList.toggle('override',override);});document.querySelector('#profile-test-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;const target=document.querySelector('#profile-test-result');target.innerHTML='<div class="loading-page"><span class="spinner"></span></div>';try{const data=Object.fromEntries(new FormData(event.currentTarget));const result=await post(`/api/profiles/${encodeURIComponent(profileId)}/test-chat`,{...data,max_output_tokens:Number(data.max_output_tokens)});target.innerHTML=`<div class="notice good">Connection/model test completed${result.model_override?' with a temporary model override':''}.</div><div class="mini-grid section-gap"><div class="mini-stat"><span>Status</span><strong>${e(result.status)}</strong></div><div class="mini-stat"><span>Latency</span><strong>${e(result.latency_ms)} ms</strong></div><div class="mini-stat"><span>Model</span><strong>${e(result.model)}</strong></div><div class="mini-stat"><span>Usage delta</span><strong>${e(result.usage_delta?JSON.stringify(result.usage_delta):'Unknown')}</strong></div></div><h3>Response</h3><pre class="json">${e(result.response)}</pre>`;}catch(error){target.innerHTML=`<div class="notice warn">${e(error.code)} · ${e(error.message)}</div>`;}finally{button.disabled=false;}});}

async function modelsPage(){const models=await api('/api/models');return `${head('Models','Installed model inventory. Unknown facts are displayed as unknown, never guessed.',`<button class="button" data-action="refresh-models">↻ Rediscover</button>`)}<article class="card"><div class="toolbar"><input class="input" id="model-search" placeholder="Search model or provider…"><span class="muted">${models.filter(m=>m.model_id).length} discovered</span></div>${models.some(m=>m.model_id)?`<div class="table-wrap"><table class="data-table" id="models-table"><thead><tr><th>Model</th><th>Provider</th><th>Loaded</th><th>Context</th><th>Strength</th><th>Tools</th><th>Vision</th><th>Availability</th></tr></thead><tbody>${models.filter(m=>m.model_id).map(m=>{const d=m.discovered_facts||{};const h=m.heuristic_estimates||{};return `<tr data-search="${e(`${m.model_id} ${m.provider_id}`.toLowerCase())}"><td><div class="row-title mono">${e(m.model_id)}</div><div class="row-sub">${e(d.family||'Family unknown')} · ${bytes(d.parameter_size)}</div></td><td>${e(m.provider_id)}</td><td>${badge(d.loaded===true?'loaded':d.loaded===false?'unloaded':'unknown')}</td><td>${e(d.context_size??'Unknown')}</td><td>${e(m.configured_overrides?.strength_class||h.strength_class||'Unknown')}</td><td>${e(d.tool_support??'Unknown')}</td><td>${e(d.vision??'Unknown')}</td><td>${badge(m.availability)}</td></tr>`}).join('')}</tbody></table></div>`:empty('No models discovered','Start the local provider or enable a provider with model discovery.','◌')}</article>`;}

const lifecycle=['CREATED','READY','ROUTING','RUNNING','WAITING_VALIDATION','COMPLETED'];
async function tasksPage(){const [tasks,projects]=await Promise.all([api('/api/tasks'),api('/api/projects')]);return `${head('Tasks','Durable task records, execution attempts, validation, and safe resume.',`<button class="button primary" data-action="create-task">＋ Create task</button>`)}<article class="card"><div class="toolbar"><input class="input" id="task-search" placeholder="Search task or objective…"><select class="select" id="task-project" style="max-width:240px"><option value="">All projects</option>${projects.map(p=>`<option value="${e(p.projectId)}">${e(p.displayName)}</option>`).join('')}</select><span class="muted" id="task-live-note"></span></div>${tasks.length?`<div class="table-wrap"><table class="data-table" id="tasks-table"><thead><tr><th>Task</th><th>Project</th><th>State</th><th>Risk</th><th>Updated</th><th></th></tr></thead><tbody>${tasks.map(({descriptor:d,state:s})=>`<tr data-task-key="${e(`${d.project_id}:${d.task_id}`)}" data-project="${e(d.project_id)}" data-search="${e(`${d.task_id} ${d.objective}`.toLowerCase())}"><td><div class="row-title mono">${e(d.task_id)}</div><div class="row-sub">${e(d.objective)}</div></td><td class="mono">${e(d.project_id)}</td><td data-task-state>${badge(s?.state||d.current_state)}</td><td>${badge(d.risk)}</td><td data-task-updated>${ago(s?.updated_at||d.updated_at)}</td><td><button class="button small" data-action="task-detail" data-project="${e(d.project_id)}" data-id="${e(d.task_id)}">Inspect</button></td></tr>`).join('')}</tbody></table></div>`:empty('No durable tasks','Create a task descriptor. It will not execute until you explicitly resume it.','✓')}</article>`;}

async function routingPage(){const [providers,profiles,models]=await Promise.all([api('/api/providers'),api('/api/profiles'),api('/api/models')]);return `${head('Routing explanation','Explore hard rules, optional Jev classification, and the final auditable decision. This view never executes a task.')}<section class="grid two"><form class="card card-pad" id="routing-form"><h3>Task requirements</h3><div class="form-grid section-gap"><div class="field wide"><label>Objective</label><input class="input" name="objective" placeholder="Describe the routing scenario"></div><div class="field"><label>Task type</label><select class="select" name="task_type"><option>general</option><option>coding</option><option>analysis</option></select></div><div class="field"><label>Risk</label><select class="select" name="risk"><option>low</option><option>medium</option><option>high</option><option>critical</option></select></div><div class="field"><label>Required capabilities</label><input class="input" name="capability" placeholder="coding, tool_use"></div><div class="field"><label>Manual provider</label><select class="select" name="provider"><option value="">Automatic</option>${providers.map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label>Manual profile</label><select class="select" name="profile"><option value="">Automatic</option>${profiles.map(p=>`<option value="${e(p.profile_id)}">${e(p.display_name)}</option>`).join('')}</select></div><div class="field"><label>Manual model</label><select class="select" name="model"><option value="">Automatic</option>${models.filter(m=>m.model_id).map(m=>`<option value="${e(m.model_id)}">${e(m.model_id)}</option>`).join('')}</select></div><label class="check-row wide"><input type="checkbox" name="allow_metered"> Allow metered providers only if globally enabled</label></div><button class="button primary section-gap" type="submit">Explain route</button></form><article class="card" id="route-result">${empty('Awaiting requirements','Submit the form to see accepted and rejected candidates.','⇢')}</article></section>`;}
function routeResult(x){const selected=x.selected,d=x.decision_engine||{};const classification=d.classification;return `<div class="card-header"><div><h3>Final decision</h3><p>Policy ${e(x.policy_version)} · ${e(d.decision_source||'deterministic')}</p></div>${badge(selected?'route found':'no eligible route')}</div><div class="card-pad"><h4>Hard rules</h4><div class="reason-list"><span class="reason">${x.rejected_candidates.length} rejected by policy</span><span class="reason">capabilities enforced</span><span class="reason">cost enforced</span><span class="reason">availability enforced</span></div><h4 class="section-gap">Jev classification</h4>${classification?`<div class="mini-grid"><div class="mini-stat"><span>Complexity</span><strong>${e(classification.task_complexity.value)} ${Math.round((classification.task_complexity.confidence??0)*100)}%</strong></div><div class="mini-stat"><span>Required strength</span><strong>${e(classification.required_strength.value)} ${Math.round((classification.required_strength.confidence??0)*100)}%</strong></div><div class="mini-stat"><span>Blast radius</span><strong>${classification.high_blast_radius.value?'Yes':'No'} ${Math.round((classification.high_blast_radius.confidence??0)*100)}%</strong></div><div class="mini-stat"><span>Local suitability</span><strong>${Math.round(classification.local_suitability.value*100)}%</strong></div></div>`:`<div class="notice">Jev: ${e(d.fallback_reason||'Disabled')}</div>`}<h4 class="section-gap">Deterministic policy</h4><p class="muted">Hard policy remained authoritative. Fallback: ${d.fallback?`Yes — ${e(d.fallback_reason)}`:'Not required'}.</p></div>${selected?`<div class="route-summary"><div class="route-winner"><small>Selected</small><strong>${e(selected.provider_id)}</strong><span class="mono">${e(selected.profile_id)} · ${e(selected.model_id||'default')}</span></div><div><div class="reason-list">${selected.reasons.map(r=>`<span class="reason">${e(r)}</span>`).join('')}</div></div></div>`:`<div class="notice warn" style="margin:16px">${e(x.error?.message||'No route available.')}</div>`}<div class="table-wrap"><table class="data-table"><thead><tr><th>Candidate</th><th>Decision</th><th>Score</th><th>Reasons</th></tr></thead><tbody>${x.evaluations.map(c=>`<tr><td><div class="row-title">${e(c.provider_id)} / ${e(c.profile_id)}</div><div class="row-sub mono">${e(c.model_id||'default')}</div></td><td>${badge(c.eligible?'accepted':'rejected')}</td><td>${e(c.score??'—')}</td><td><div class="reason-list">${[...c.reasons,...c.rejected].map(r=>`<span class="reason ${c.rejected.includes(r)?'reject':''}">${e(r)}</span>`).join('')}</div></td></tr>`).join('')}</tbody></table></div>`;}

async function projectSelector(label){const projects=await api('/api/projects');if(!state.selectedProject&&projects.length)state.selectedProject=projects[0].projectId;return `<div class="field"><label>${e(label)}</label><select class="select" id="continuity-project"><option value="">Choose a project</option>${projects.map(p=>`<option value="${e(p.projectId)}" ${p.projectId===state.selectedProject?'selected':''}>${e(p.displayName)}</option>`).join('')}</select></div>`;}
