async function locksPage(){const locks=await api('/api/locks');return `${head('Locks','Project leases prevent unsafe concurrent execution.')}<article class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>Status</th><th>Owner PID</th><th>Host</th><th>Age</th></tr></thead><tbody id="locks-body">${locksRows(locks)}</tbody></table></div></article>`;}
