async function auditPage(){const events=await api('/api/audit');return `${head('Audit / Logs','Sanitized, append-only operational facts. Private prompts and provider bodies are excluded.')}<article class="card"><div class="toolbar"><input class="input" id="audit-search" placeholder="Filter event, project, task…"><span class="muted" id="audit-count">Latest ${events.length} events</span></div>${events.length?`<div class="table-wrap"><table class="data-table" id="audit-table"><thead><tr><th>Time</th><th>Event</th><th>Project</th><th>Task / Provider</th></tr></thead><tbody id="audit-body">${auditRows(events)}</tbody></table></div>`:empty('No audit events','Operational events will appear here.','≡')}</article>`;}
async function doctorPage(){const [d,tasks]=await Promise.all([api('/api/doctor'),api('/api/tasks')]);return `${head('System doctor','Evidence-based checks for runtime data, projects, providers, memory, Git, locks, and selected tasks.',`<button class="button" data-action="copy-diagnostics">▣ Copy diagnostics</button>`)}<section class="grid metrics">${metric('Overall status',d.status,'Current diagnostic result')}${metric('Version',d.version,'AI Router release')}${metric('Checks',d.checks.length,`${d.checks.filter(x=>x.status==='ok').length} passing`)}${metric('Generated',ago(d.generated_at),'Diagnostic freshness')}</section><article class="card section-gap"><div class="card-header"><div><h3>Task safety diagnosis</h3><p>Select a durable task for descriptor, memory, journal, lock, drift, provider, and resume evidence.</p></div><select class="select" id="task-doctor-select" style="max-width:320px"><option value="">Choose task</option>${tasks.map(({descriptor:d})=>`<option value="${e(`${d.project_id}::${d.task_id}`)}">${e(d.task_id)}</option>`).join('')}</select></div><div id="task-doctor-result">${empty('No task selected','Choose a task to run task-specific diagnostics.','✚')}</div></article><section class="grid two section-gap">${d.checks.map(c=>`<article class="card card-pad"><div class="split"><h3>${e(c.name.replaceAll('_',' '))}</h3>${badge(c.status)}</div><div class="section-gap">${c.error?`<div class="notice warn">${e(c.error.code)} · ${e(c.error.message)}</div>`:jsonView(c.details)}</div></article>`).join('')}</section>`;}
async function settingsPage(){const [s,d]=await Promise.all([api('/api/settings'),api('/api/decision-engines/config')]);return `${head('Settings','Safe local control-plane preferences. Provider credentials are deliberately absent.')}<form class="card card-pad" id="settings-form"><div class="form-grid"><div class="field"><label>Preferred port</label><input class="input" type="number" name="port" min="1024" max="65535" value="${e(s.port)}"><small class="muted">Applied on the next service start; collisions select the next available local port.</small></div><div class="field"><label>Health refresh interval (seconds)</label><input class="input" type="number" name="refresh" min="10" max="60" value="${e(Math.min(60,Math.max(10,s.refresh_interval_ms/1000)))}"><small class="muted">Task state uses 4 seconds; static observations use 45 seconds.</small></div><div class="field"><label>Maximum attempts</label><input class="input" type="number" name="max_attempts" min="1" max="10" value="${e(s.max_attempts)}"></div><div class="field"><label>Theme</label><select class="select" name="theme"><option value="system" ${s.theme==='system'?'selected':''}>System</option><option value="light" ${s.theme==='light'?'selected':''}>Light</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option></select></div><label class="check-row"><input type="checkbox" name="prefer_local" ${s.prefer_local?'checked':''}> Prefer local capacity</label><label class="check-row"><input type="checkbox" name="prefer_subscription" ${s.prefer_subscription?'checked':''}> Prefer included subscriptions</label><label class="check-row"><input type="checkbox" name="allow_metered" ${s.allow_metered?'checked':''}> Allow metered providers</label></div><div class="notice warn section-gap">Metered capacity remains off by default. Enabling it here never creates credentials or connects an unimplemented provider.</div><button class="button primary section-gap" type="submit">Save system settings</button></form><form class="card card-pad section-gap" id="decision-settings-form"><h3>Decision Engine</h3><p class="muted">Jev is optional and off by default. Changes apply immediately without a restart.</p><div class="form-grid section-gap"><div class="field"><label>Routing mode</label><select class="select" name="mode"><option value="deterministic_only" ${d.mode==='deterministic_only'?'selected':''}>Deterministic Only</option><option value="jev_assisted" ${d.mode==='jev_assisted'?'selected':''}>Jev Assisted</option><option value="hybrid" ${d.mode==='hybrid'?'selected':''}>Hybrid</option></select></div><label class="check-row"><input type="checkbox" name="enabled" ${d.enabled?'checked':''}> Jev enabled</label><label class="check-row"><input type="checkbox" name="fallback_enabled" ${d.fallback_enabled?'checked':''}> Deterministic fallback enabled</label><div class="field"><label>Confidence threshold</label><input class="input" type="number" name="confidence_threshold" min="0" max="1" step="0.01" value="${e(d.confidence_threshold)}"></div><div class="field"><label>Minimum usable confidence</label><input class="input" type="number" name="minimum_confidence" min="0" max="1" step="0.01" value="${e(d.minimum_confidence)}"></div><div class="field"><label>Timeout (ms)</label><input class="input" type="number" name="timeout_ms" min="100" max="30000" value="${e(d.timeout_ms)}"></div><label class="check-row"><input type="checkbox" name="initial_routing" ${d.usage_categories.initial_routing?'checked':''}> Initial routing</label><label class="check-row"><input type="checkbox" name="retry_escalation" ${d.usage_categories.retry_escalation?'checked':''}> Retry / escalation</label><label class="check-row"><input type="checkbox" name="action_risk" ${d.usage_categories.action_risk?'checked':''}> Action risk</label><label class="check-row"><input type="checkbox" name="handoff_quality" ${d.usage_categories.handoff_quality?'checked':''}> Handoff quality</label><label class="check-row"><input type="checkbox" name="context_relevance" ${d.usage_categories.context_relevance?'checked':''}> Context relevance</label><div class="field"><label>Maximum estimated daily spend</label><input class="input" type="number" name="daily_budget" min="0" step="0.01" value="${e(d.budgets.maximum_estimated_daily_spend??'')}"></div><div class="field"><label>Maximum estimated monthly spend</label><input class="input" type="number" name="monthly_budget" min="0" step="0.01" value="${e(d.budgets.maximum_estimated_monthly_spend??'')}"></div></div><div class="notice section-gap">Only initial routing is enabled as a Jev usage category by default. Real Jev connectivity is not implemented.</div><button class="button primary section-gap" type="submit">Save decision settings</button></form>`;}

function replaceHtml(element, html){if(element&&element.innerHTML!==html)element.innerHTML=html;}
function updateMetric(key,value,note){const card=document.querySelector(`[data-metric="${key}"]`);if(!card)return;const valueNode=card.querySelector('.metric-value');const noteNode=card.querySelector('.metric-note');if(valueNode&&valueNode.textContent!==String(value))valueNode.textContent=String(value);if(noteNode&&noteNode.textContent!==String(note))noteNode.textContent=String(note);}
function updateHealth(key,status,note){const item=document.querySelector(`[data-health="${key}"]`);if(!item)return;const noteNode=item.querySelector('small');if(noteNode&&noteNode.textContent!==String(note))noteNode.textContent=String(note);const existing=item.querySelector('.badge');if(existing&&existing.outerHTML!==badge(status))existing.outerHTML=badge(status);}
function markFresh(){state.lastGoodRefresh=new Date();const label=document.querySelector('#last-refresh');if(label){label.classList.remove('stale','syncing');label.textContent=`Updated ${state.lastGoodRefresh.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;}document.querySelector('#connection-dot').className='connection-dot ok';document.querySelector('#connection-label').textContent='Local service ready';}
function markStale(){const label=document.querySelector('#last-refresh');if(label){label.classList.remove('syncing');label.classList.add('stale');label.textContent=`State may be stale · last good ${state.lastGoodRefresh?state.lastGoodRefresh.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'unknown'}`;}document.querySelector('#connection-dot').className='connection-dot';document.querySelector('#connection-label').textContent='Using last known state';}
function markSyncing(){const label=document.querySelector('#last-refresh');if(label&&!label.classList.contains('stale'))label.classList.add('syncing');}

async function refreshGlobalStatus(){const status=await api('/api/status');document.querySelector('#version-label').textContent=`v${status.version} · 127.0.0.1`;if(state.route==='overview'){updateMetric('projects',status.counts.projects,`${status.counts.projects} registered`);updateMetric('providers',status.counts.healthy_providers,`${status.counts.providers} registered`);updateMetric('tasks',status.counts.active_tasks,`${status.counts.tasks} durable records`);updateHealth('control','healthy',`127.0.0.1 · uptime ${duration(status.control?.uptime_seconds)}`);replaceHtml(document.querySelector('#overview-system-status'),badge(status.status));}return status;}
async function refreshTasks(){const tasks=await api('/api/tasks');const active=tasks.filter(item=>!['COMPLETED','CANCELLED'].includes(item.state?.state));if(state.route==='overview'){updateMetric('tasks',active.length,`${tasks.length} durable records`);updateHealth('tasks',active.length?'running':'ready',`${active.length} active`);}if(state.route==='tasks'){const rows=[...document.querySelectorAll('[data-task-key]')];const byKey=new Map(tasks.map(item=>[`${item.descriptor.project_id}:${item.descriptor.task_id}`,item]));for(const row of rows){const item=byKey.get(row.dataset.taskKey);if(!item)continue;replaceHtml(row.querySelector('[data-task-state]'),badge(item.state?.state||item.descriptor.current_state));const updated=row.querySelector('[data-task-updated]');if(updated)updated.textContent=ago(item.state?.updated_at||item.descriptor.updated_at);}const note=document.querySelector('#task-live-note');if(note)note.textContent=rows.length===tasks.length?'Live status':`${Math.abs(tasks.length-rows.length)} list change(s) available`; }return tasks;}
async function refreshOverview(){const results=await Promise.allSettled([api('/api/projects'),api('/api/providers'),api('/api/audit')]);if(results[0].status==='fulfilled'){const projects=results[0].value;const initialized=projects.filter(item=>item.memory_initialized).length;updateMetric('projects',projects.length,`${projects.filter(item=>item.status==='active').length} active`);updateMetric('continuity',initialized,`${projects.length-initialized} need memory`);updateHealth('memory',projects.every(item=>item.memory_initialized)?'healthy':'review',`${initialized}/${projects.length} initialized`);}if(results[1].status==='fulfilled'){const providers=results[1].value;updateMetric('providers',providers.filter(item=>item.health.status==='healthy').length,`${providers.length} registered`);for(const provider of providers){updateHealth(`provider-${provider.id}`,provider.health.status,`${provider.health.model_count??0} models`);const card=document.querySelector(`[data-provider-id="${provider.id}"]`);if(card){replaceHtml(card.querySelector('[data-provider-status]'),badge(provider.enabled?provider.health.status:'disabled'));const count=card.querySelector('[data-provider-models]');if(count)count.textContent=provider.health.model_count??'Unknown';}}}if(results[2].status==='fulfilled'){const audit=results[2].value;replaceHtml(document.querySelector('#overview-activity'),audit.length?`<ul class="activity-list">${audit.slice(0,7).map(activity).join('')}</ul>`:empty('No audit events','Events will appear as the router performs local operations.','≡'));replaceHtml(document.querySelector('#overview-routing'),routingSummary(audit.find(item=>item.type==='route_selected')));}if(results.some(result=>result.status==='rejected'))throw new Error('One or more overview sources are temporarily unavailable.');}
async function refreshProviders(){const providers=await api('/api/providers');for(const provider of providers){const card=document.querySelector(`[data-provider-id="${provider.id}"]`);if(!card)continue;replaceHtml(card.querySelector('[data-provider-status]'),badge(provider.enabled?provider.health.status:'disabled'));const count=card.querySelector('[data-provider-models]');if(count)count.textContent=provider.health.model_count??'Unknown';}}
async function refreshDecisionEngines(){const s=await api('/api/decision-engines/status');const last=s.last_decision;replaceHtml(document.querySelector('[data-jev="health"]'),badge(s.health.status));for(const [key,value] of [['enabled',s.enabled?'Yes':'No'],['mode',s.mode.replaceAll('_',' ')],['last-decision',last?.at?ago(last.at):'Never'],['latency',last?.latency_ms==null?'Unknown':`${last.latency_ms} ms`],['confidence',last?.confidence==null?'Unknown':`${Math.round(last.confidence*100)}%`],['error',last?.fallback_reason||'None']]){const target=document.querySelector(`[data-jev="${key}"]`);if(target)target.textContent=value;}}
async function refreshProjects(){const projects=await api('/api/projects');for(const project of projects){const row=document.querySelector(`[data-project-id="${project.projectId}"]`);if(!row)continue;replaceHtml(row.querySelector('[data-project-status]'),badge(project.status));replaceHtml(row.querySelector('[data-project-git]'),badge(project.git?.dirty===false?'clean':project.git?.isRepository?'changed':'not git'));replaceHtml(row.querySelector('[data-project-memory]'),badge(project.memory_status));replaceHtml(row.querySelector('[data-project-task]'),project.active_task?`<span class="mono">${e(project.active_task.task_id)}</span>`:'—');}}
async function refreshLocks(){const body=document.querySelector('#locks-body');if(body)replaceHtml(body,locksRows(await api('/api/locks')));}
async function refreshAudit(){const events=await api('/api/audit');const body=document.querySelector('#audit-body');if(body){replaceHtml(body,auditRows(events));const query=document.querySelector('#audit-search')?.value.toLowerCase()||'';body.querySelectorAll('tr').forEach(row=>row.hidden=!row.dataset.search.includes(query));}const count=document.querySelector('#audit-count');if(count)count.textContent=`Latest ${events.length} events`;}
async function refreshCurrent(kind='manual'){
  if(state.pollBusy.has(kind)||document.visibilityState!=='visible')return;state.pollBusy.add(kind);markSyncing();
  try{if(kind==='health'||kind==='manual')await refreshGlobalStatus();if((kind==='tasks'||kind==='manual')&&['overview','tasks'].includes(state.route))await refreshTasks();if((kind==='health'||kind==='manual')&&state.route==='overview')await refreshOverview();if((kind==='health'||kind==='manual')&&state.route==='providers')await refreshProviders();if((kind==='health'||kind==='manual')&&state.route==='decision-engines')await refreshDecisionEngines();if((kind==='static'||kind==='manual')&&state.route==='projects')await refreshProjects();if((kind==='tasks'||kind==='manual')&&state.route==='locks')await refreshLocks();if((kind==='static'||kind==='manual')&&state.route==='audit')await refreshAudit();markFresh();}
  catch{markStale();}finally{state.pollBusy.delete(kind);}
}
function startPolling(healthInterval=POLL_INTERVALS.health){for(const timer of state.pollTimers)clearInterval(timer);state.pollTimers=[setInterval(()=>refreshCurrent('tasks'),POLL_INTERVALS.tasks),setInterval(()=>refreshCurrent('health'),Math.min(60_000,Math.max(10_000,healthInterval))),setInterval(()=>refreshCurrent('static'),POLL_INTERVALS.static)];}

const renderers={overview,projects:projectsPage,providers:providersPage,profiles:profilesPage,models:modelsPage,tasks:tasksPage,routing:routingPage,'decision-engines':decisionEnginesPage,memory:memoryPage,handoffs:handoffsPage,checkpoints:checkpointsPage,locks:locksPage,audit:auditPage,doctor:doctorPage,settings:settingsPage};
let renderGeneration=0;
async function render(){const generation=++renderGeneration;const route=state.route;pageChrome();workspace.innerHTML='<div class="loading-page"><span class="spinner"></span><p>Reading durable local state…</p></div>';try{const content=await (renderers[route]||overview)();if(generation!==renderGeneration)return;workspace.innerHTML=content;document.querySelector('#last-refresh').textContent=`Refreshed ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;document.querySelector('#connection-dot').className='connection-dot ok';document.querySelector('#connection-label').textContent='Local service ready';bindPage();}catch(error){if(generation!==renderGeneration)return;workspace.innerHTML=`<div class="error-page"><span class="error-code">${e(error.code||'REQUEST_FAILED')}</span><h2>Could not load this view</h2><p class="muted">${e(error.message)}</p><button class="button primary" data-action="retry">Try again</button></div>`;document.querySelector('#connection-dot').className='connection-dot bad';document.querySelector('#connection-label').textContent='Disconnected';}}

function taskTabContent(name){const t=state.taskDetail;if(!t)return '';if(name==='attempts')return jsonView(t.attempts);if(name==='journal')return jsonView(t.recovery_journal);if(name==='resume')return jsonView(t.resume);return jsonView({descriptor:t.descriptor,current_state:t.state,execution_plan:t.execution_plan});}
async function taskDetail(project,id){drawer('Task details','<div class="loading-page"><span class="spinner"></span></div>');try{const t=await api(`/api/projects/${encodeURIComponent(project)}/tasks/${encodeURIComponent(id)}`);state.taskDetail=t;state.taskTab='descriptor';const current=t.state.state;const index=lifecycle.indexOf(current);drawer(t.descriptor.task_id,`<div class="split"><div><p class="eyebrow">${e(t.descriptor.project_id)}</p><h3>${e(t.descriptor.objective)}</h3></div>${badge(current)}</div><div class="timeline section-gap">${lifecycle.map((x,i)=>`<div class="timeline-step ${i<index||current==='COMPLETED'?'done':''} ${i===index?'current':''}"><div class="step-dot">${i<index?'✓':i+1}</div><span>${x.replace('_',' ')}</span></div>`).join('')}</div><div class="actions section-gap">${!['COMPLETED','CANCELLED'].includes(current)?`<button class="button primary" data-action="resume-task" data-project="${e(project)}" data-id="${e(id)}">Resume safely</button><button class="button danger" data-action="cancel-task" data-project="${e(project)}" data-id="${e(id)}">Cancel</button>`:''}</div><div class="tabs section-gap"><button class="tab active" data-action="task-tab" data-id="descriptor">Descriptor</button><button class="tab" data-action="task-tab" data-id="attempts">Attempts (${t.attempts.length})</button><button class="tab" data-action="task-tab" data-id="journal">Journal (${t.recovery_journal.length})</button><button class="tab" data-action="task-tab" data-id="resume">Resume</button></div><div id="task-tab-content">${taskTabContent('descriptor')}</div>`);}catch(error){drawer('Task details',`<div class="notice warn">${e(error.code)} · ${e(error.message)}</div>`);}}

function bindPage(){
  document.querySelector('#routing-form')?.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget);const params=new URLSearchParams();for(const [k,v] of data){if(k==='capability')String(v).split(',').map(x=>x.trim()).filter(Boolean).forEach(x=>params.append(k,x));else params.set(k,k==='allow_metered'?'true':v);}const result=document.querySelector('#route-result');result.innerHTML='<div class="loading-page"><span class="spinner"></span></div>';try{result.innerHTML=routeResult(await api(`/api/routing/explain?${params}`));}catch(error){result.innerHTML=`<div class="notice warn" style="margin:16px">${e(error.message)}</div>`;}});
  document.querySelector('#continuity-project')?.addEventListener('change',event=>{state.selectedProject=event.target.value;render();});
  document.querySelector('#settings-form')?.addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget;try{const saved=await post('/api/settings',{port:Number(f.port.value),refresh_interval_ms:Number(f.refresh.value)*1000,max_attempts:Number(f.max_attempts.value),theme:f.theme.value,prefer_local:f.prefer_local.checked,prefer_subscription:f.prefer_subscription.checked,allow_metered:f.allow_metered.checked});state.theme=saved.theme;document.documentElement.dataset.theme=state.theme;startPolling(saved.refresh_interval_ms);toast('Settings saved.');}catch(error){toast(`${error.code}: ${error.message}`,'bad');}});
  document.querySelector('#developer-test-mode')?.addEventListener('change',async event=>{try{await post('/api/settings',{developer_test_mode:event.target.checked});await render();}catch(error){toast(`${error.code}: ${error.message}`,'bad');}});
  document.querySelector('#decision-settings-form')?.addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget;const optionalNumber=name=>f[name].value===''?null:Number(f[name].value);try{await post('/api/decision-engines/config',{mode:f.mode.value,enabled:f.enabled.checked,fallback_enabled:f.fallback_enabled.checked,confidence_threshold:Number(f.confidence_threshold.value),minimum_confidence:Number(f.minimum_confidence.value),timeout_ms:Number(f.timeout_ms.value),usage_categories:{initial_routing:f.initial_routing.checked,retry_escalation:f.retry_escalation.checked,action_risk:f.action_risk.checked,handoff_quality:f.handoff_quality.checked,context_relevance:f.context_relevance.checked},budgets:{maximum_estimated_daily_spend:optionalNumber('daily_budget'),maximum_estimated_monthly_spend:optionalNumber('monthly_budget')}});toast('Decision engine settings saved.');await render();}catch(error){toast(`${error.code}: ${error.message}`,'bad');}});
  document.querySelector('#task-doctor-select')?.addEventListener('change',async event=>{const target=document.querySelector('#task-doctor-result');if(!event.target.value){target.innerHTML=empty('No task selected','Choose a task to run task-specific diagnostics.','✚');return;}const [project,id]=event.target.value.split('::');target.innerHTML='<div class="loading-page"><span class="spinner"></span></div>';try{target.innerHTML=`<div class="card-pad">${jsonView(await api(`/api/projects/${encodeURIComponent(project)}/tasks/${encodeURIComponent(id)}/doctor`))}</div>`;}catch(error){target.innerHTML=`<div class="notice warn" style="margin:16px">${e(error.code)} · ${e(error.message)}</div>`;}});
  for(const [input,table] of [['#model-search','#models-table'],['#audit-search','#audit-table']])document.querySelector(input)?.addEventListener('input',event=>document.querySelectorAll(`${table} tbody tr`).forEach(row=>row.hidden=!row.dataset.search.includes(event.target.value.toLowerCase())));
  const taskFilter=()=>{const q=document.querySelector('#task-search')?.value.toLowerCase()||'';const p=document.querySelector('#task-project')?.value||'';document.querySelectorAll('#tasks-table tbody tr').forEach(row=>row.hidden=!row.dataset.search.includes(q)||(p&&row.dataset.project!==p));};document.querySelector('#task-search')?.addEventListener('input',taskFilter);document.querySelector('#task-project')?.addEventListener('change',taskFilter);
}

document.addEventListener('click',async event=>{
  const nav=event.target.closest('[data-nav]');if(nav){const next=nav.dataset.nav;if(location.hash===`#${next}`){state.route=next;render();}else location.hash=next;return;}
  if(event.target.closest('[data-close]')&&event.target===event.target.closest('[data-close]')){closeOverlays();return;}
  const action=event.target.closest('[data-action]');if(!action)return;
  try{
    if(action.dataset.action==='retry')return render();
    if(action.dataset.action==='register-project')return modal('Register project','<div class="form-grid"><div class="field wide"><label>Workspace path</label><input class="input" name="path" required placeholder="D:\\Projects\\my-project"></div><div class="field wide"><label>Display name (optional)</label><input class="input" name="display_name"></div></div>','Register',data=>post('/api/projects/register',data));
    if(action.dataset.action==='scan-projects'){await post('/api/projects/scan');toast('Configured project roots scanned.');return render();}
    if(action.dataset.action==='init-memory'){await post(`/api/projects/${encodeURIComponent(action.dataset.id)}/memory/initialize`);toast('Project memory initialized.');return render();}
    if(action.dataset.action==='project-detail'){const project=(await api('/api/projects')).find(item=>item.projectId===action.dataset.id);return drawer(project?.displayName||'Project details',jsonView(project||{}));}
    if(action.dataset.action==='project-memory'){state.selectedProject=action.dataset.id;location.hash='memory';return;}
    if(action.dataset.action==='provider-toggle'){await post(`/api/providers/${encodeURIComponent(action.dataset.id)}/${action.dataset.enabled==='true'?'disable':'enable'}`);toast('Provider state updated.');return render();}
    if(action.dataset.action==='test-providers'){await api('/api/providers?refresh=true');toast('Provider health refreshed.');return render();}
    if(action.dataset.action==='refresh-models'){await api('/api/models?refresh=true');toast('Model inventory refreshed.');return render();}
    if(action.dataset.action==='discover-models'){await api('/api/models?refresh=true');location.hash='models';toast('Model inventory refreshed.');return;}
    if(action.dataset.action==='add-profile')return profileEditor();
    if(action.dataset.action==='profile-edit')return profileEditor((state.visibleProfiles||[]).find(item=>item.profile_id===action.dataset.id));
    if(action.dataset.action==='profile-connect'){const profile=(state.visibleProfiles||[]).find(item=>item.profile_id===action.dataset.id);if(!profile)throw Object.assign(new Error('Profile is no longer available.'),{code:'PROFILE_NOT_FOUND'});return profileConnect(profile,action.dataset.connectAction||'connect');}
    if(action.dataset.action==='profile-disconnect'){await post(`/api/profiles/${encodeURIComponent(action.dataset.id)}/disconnect`);toast('Profile disconnected.');return render();}
    if(action.dataset.action==='profile-toggle'){await post(`/api/profiles/${encodeURIComponent(action.dataset.id)}/${action.dataset.enabled==='true'?'disable':'enable'}`);toast('Profile state updated.');return render();}
    if(action.dataset.action==='profile-test-connection'){const result=await post(`/api/profiles/${encodeURIComponent(action.dataset.id)}/test-connection`);return drawer('Test Connection',`<div class="mini-grid"><div class="mini-stat"><span>Authentication</span><strong>${e(result.auth.status)}</strong></div><div class="mini-stat"><span>Reachable</span><strong>${result.reachable?'Yes':'No'}</strong></div><div class="mini-stat"><span>Health</span><strong>${e(result.health.status)}</strong></div><div class="mini-stat"><span>Models</span><strong>${result.model_list_available?e(result.models.length):'Unknown'}</strong></div><div class="mini-stat"><span>Plan</span><strong>${e(result.plan_type??'Unknown')}</strong></div><div class="mini-stat"><span>Usage</span><strong>${result.usage?.available?e(JSON.stringify(result.usage)):'Unavailable'}</strong></div><div class="mini-stat"><span>Limits</span><strong>${result.limits?.available?e(JSON.stringify(result.limits)):'Unavailable'}</strong></div></div>${result.models.length?`<pre class="json section-gap">${e(result.models.join('\n'))}</pre>`:''}`);}
    if(action.dataset.action==='profile-test-chat')return profileTestChat(action.dataset.id,action.dataset.provider);
    if(action.dataset.action==='profile-delete'){if(!confirm('Delete this profile and its encrypted local credential?'))return;await post(`/api/profiles/${encodeURIComponent(action.dataset.id)}/delete`);toast('Profile and stored credential deleted.');return render();}
    if(action.dataset.action==='connect-jev'){return toast('Real Jev connection not enabled yet.');}
    if(action.dataset.action==='create-task'){const projects=await api('/api/projects');return modal('Create durable task',`<div class="form-grid"><div class="field wide"><label>Project</label><select class="select" name="project_id" required><option value="">Choose project</option>${projects.map(p=>`<option value="${e(p.projectId)}">${e(p.displayName)}</option>`).join('')}</select></div><div class="field wide"><label>Objective</label><input class="input" name="objective" required maxlength="2000"></div><div class="field"><label>Risk</label><select class="select" name="risk"><option>low</option><option>medium</option><option>high</option><option>critical</option></select></div><div class="field"><label>Task ID (optional)</label><input class="input" name="task_id" pattern="[a-z0-9][a-z0-9._-]{1,79}"></div><div class="field wide"><label>Execution instruction</label><textarea class="textarea" name="instruction" placeholder="Instructions are persisted in the private runtime descriptor."></textarea></div></div>`,'Create',data=>post('/api/tasks',{...data,task_id:data.task_id||undefined}));}
    if(action.dataset.action==='task-detail')return taskDetail(action.dataset.project,action.dataset.id);
    if(action.dataset.action==='task-tab'){state.taskTab=action.dataset.id;document.querySelectorAll('.drawer .tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.id===state.taskTab));document.querySelector('#task-tab-content').innerHTML=taskTabContent(state.taskTab);return;}
    if(action.dataset.action==='resume-task'){if(!confirm('Resume this task using its persisted safety checks and routing policy?'))return;await post(`/api/projects/${encodeURIComponent(action.dataset.project)}/tasks/${encodeURIComponent(action.dataset.id)}/resume`);toast('Resume operation completed.');closeOverlays();return render();}
    if(action.dataset.action==='cancel-task'){if(!confirm('Cancel this task? This records a durable terminal state.'))return;await post(`/api/projects/${encodeURIComponent(action.dataset.project)}/tasks/${encodeURIComponent(action.dataset.id)}/cancel`);toast('Task cancelled.');closeOverlays();return render();}
    if(action.dataset.action==='memory-tab'){state.memoryTab=action.dataset.id;return render();}
    if(action.dataset.action==='copy-diagnostics'){const value=await api('/api/doctor');await navigator.clipboard.writeText(JSON.stringify(value,null,2));return toast('Diagnostics copied.');}
  }catch(error){toast(`${error.code}: ${error.message}`,'bad');}
});
document.querySelector('#refresh-button').addEventListener('click',()=>refreshCurrent('manual'));
document.querySelector('#menu-button').addEventListener('click',()=>document.body.classList.toggle('menu-open'));
document.querySelector('#theme-button').addEventListener('click',async()=>{const cycle={system:'light',light:'dark',dark:'system'};state.theme=cycle[state.theme]||'system';document.documentElement.dataset.theme=state.theme;try{await post('/api/settings',{theme:state.theme});}catch{}toast(`Theme: ${state.theme}`);});
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'overview';render();});

try{const status=await api('/api/status');state.theme=status.settings.theme||'system';document.documentElement.dataset.theme=state.theme;document.querySelector('#connection-dot').className='connection-dot ok';document.querySelector('#connection-label').textContent='Local service ready';document.querySelector('#version-label').textContent=`v${status.version} · 127.0.0.1`;await render();markFresh();startPolling(status.settings.refresh_interval_ms);}catch(error){workspace.innerHTML=`<div class="error-page"><span class="error-code">${e(error.code||'OFFLINE')}</span><h2>Local service unavailable</h2><p class="muted">${e(error.message)}</p></div>`;document.querySelector('#connection-dot').className='connection-dot bad';document.querySelector('#connection-label').textContent='Offline';}
